MODULE_GUIDE = {
"资料分析": {"core":"先定位口径，再建立数量关系，最后依据选项差距决定精度。","fast":"能比较不精算，能估算不长除；所有近似都必须知道误差方向。","risk":"最常见失分不是不会公式，而是主体、时间、单位、问法和精度控制出错。","teachers":"主方法以花生十三体系中高复用的 ABRX、份数、截位直除、比较思维为骨架，再用真题和个人数据筛选。"},
"判断推理": {"core":"先识别题型，再选最短推理链；形式逻辑题必须区分充分必要，论证题必须拆论据、缺口、结论。","fast":"图推先看特征而非机械扫规律；分析推理条件多就落表；论证题先找评价维度。","risk":"最大的风险是凭语感和局部匹配，而不是完成关系闭环。","teachers":"优先吸收阿里木江、红领巾及高质量公开判断体系中可被逻辑规则验证的方法。"},
"言语理解": {"core":"结构、主题词、语境约束优先于口诀；选项比较必须回到文段功能和作者表达目标。","fast":"先判题型和阅读目标，再读文段；纠结时比较主体、范围、程度、逻辑关系。","risk":"过度依赖‘转折后必重点’‘问题后必对策’等绝对化口诀会稳定制造错题。","teachers":"主方法以结构化阅读为核心，吸收阿里木江等成熟体系，但不保留无法被真题稳定验证的绝对口诀。"},
"数量关系": {"core":"数量不是把题做完，而是最快判断是否值得做、该用什么模型、何时止损。","fast":"前15-30秒优先扫代入、数字特性、赋值、比例、高频模型；路径仍不清晰就后置。","risk":"会做但慢是高基础考生常见陷阱，必须把识别、建模、计算、止损分开记录。","teachers":"优先吸收花生十三、陈怀安等强调短路径和考场取舍的方法，再按个人速度验证。"},
"政治理论与常识": {"core":"稳定知识与动态时政分开管理，政治理论优先掌握框架和规范表述。","fast":"高频政治理论可形成结构化关键词；低收益冷知识不做无限扩张。","risk":"常识最容易陷入资料囤积，必须控制边际收益。","teachers":"稳定事实以官方材料为准，机构和老师只做整理层来源。"},
"广东科学推理": {"core":"把基础理科知识转成‘图像+条件+关系’的推理，不按学校考试方式做复杂推导。","fast":"先识别物理/化学/生物/实验类型，再调用少量高频关系。","risk":"公式会但图像读错、条件漏读、生活直觉替代物理规律，是主要失分来源。","teachers":"以广东真题规律和基础科学规则为主，培训方法只作为题型归纳。"}
}

def get_catalog():
    return [{"module":m,"pages":len(v)} for m,v in MODULES.items()]

def get_pages(module):
    titles = MODULES[module]
    return [{"id":i+1,"title":t,"module":module} for i,t in enumerate(titles)]

def build_page(module, page_id):
    title = MODULES[module][page_id-1]
    g = MODULE_GUIDE[module]
    return {
      "id":page_id,"module":module,"title":title,
      "definition":f"本页聚焦「{title}」。学习目标不是记一句口诀，而是做到：看到题目能够快速识别这一模型、知道推荐主方法、知道什么时候可以走速解、什么时候必须回到标准方法。",
      "signals":[f"题干或材料出现与「{title}」直接相关的关键词、结构或条件。","选项结构能支持快速排除、比较或代入时，应优先利用选项信息。","若30秒内仍无法确定题型归属，应先标记而不是继续无边界尝试。"],
      "main_method":[g["core"],f"处理「{title}」时，先完成题型识别和条件抽取，再列出最少必要关系；能用比较、代入或结构判断解决时，不先做长计算。","得到答案后做一次方向、数量级、逻辑闭环或语义一致性检查。"],
      "fast_method":[g["fast"],"速解只在适用条件明确时使用；任何经验法都必须知道它为什么有效、何时会失效。"],
      "boundary":[g["risk"],"如果选项差距极小、条件存在例外、题干问法发生反向变化，优先回到标准解法。","个人连续两组真题验证前，任何‘秒杀法’只能标记为候选。"],
      "teacher_synthesis":g["teachers"],
      "review":["用自己的话复述识别信号。","不看笔记写出主解法步骤。","找1道标准题验证，再找1道变式题检查边界。","记录是否出现识别慢、推理慢、计算慢或纠结过久。"]
    }
